mkdir -p /tmp/work && cat > /tmp/work/run.py <<'E'
import urllib.request,urllib.error,json,time,datetime
B="http://localhost:8080";tok=None
def req(path,method="GET"):
    global tok
    for i in range(200):
        h={}
        if path!="/token":
            if not tok: tok=req("/token","POST")["token"]
            h["Authorization"]="Bearer "+tok
        try:
            r=urllib.request.Request(B+path,method=method,headers=h,data=b"" if method=="POST" else None)
            return json.load(urllib.request.urlopen(r,timeout=20))
        except urllib.error.HTTPError as e:
            body=e.read().decode()
            if e.code==404: return None
            if e.code==401: tok=None
            ra=e.headers.get("Retry-After")
            if ra is None:
                try: ra=json.loads(body).get("retry_after")
                except Exception: pass
            print(path,e.code,ra,body[:100],flush=True)
            time.sleep(float(ra) if ra else 1)
        except Exception as e:
            print(path,"err",e,flush=True);time.sleep(1)
    raise SystemExit("fail "+path)
orders=[];p=1;seen=set();dups=0
while True:
    d=req(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in seen: dups+=1
        else: seen.add(o["id"]);orders.append(o)
    if not d["next"]: break
    p+=1
print("pages",p,d["total_pages"],len(orders),dups)
lo=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc);hi=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
cust={};reg={"north":0,"south":0,"east":0,"west":0};n=0
for o in orders:
    if o["status"]!="shipped":continue
    t=datetime.datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: print("naive",o)
    if not(lo<=t<hi):continue
    c=o["customer_id"]
    if c not in cust: cust[c]=req("/customers/"+c)
    if cust[c] is None: print("missing customer",o);continue
    a=o["amount_cents"]*(100-cust[c]["discount_pct"])
    v=(a+50)//100
    reg[cust[c]["region"]]+=v;n+=1
r={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
json.dump(r,open("/workspace/result.json","w"),indent=2);print(r)
